import SwiftUI
import UIKit

/// The attn mascot exported from the approved Figma mascot artwork.
///
/// The image is kept as a bundled, transparent raster payload so the same
/// artwork is used in both the compact Home entry point and the landscape
/// standby surface. It is intentionally exposed as a view rather than as a
/// navigation concern.
public struct AttnMascot: View {
    private let width: CGFloat
    private let accessibilityText: String

    public init(width: CGFloat = 180, accessibilityLabel: String = "attn mascot") {
        self.width = width
        self.accessibilityText = accessibilityLabel
    }

    public var body: some View {
        Group {
            if let image = AttnMascotImage.image {
                Image(uiImage: image)
                    .resizable()
                    .interpolation(.high)
                    .scaledToFit()
            } else {
                // A quiet fallback keeps the layout usable if decoding fails.
                Image(systemName: "face.smiling")
                    .font(.system(size: width * 0.28, weight: .medium))
                    .foregroundStyle(.white)
            }
        }
        .frame(width: width, height: width * 0.643)
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(accessibilityText)
        .accessibilityAddTraits(.isImage)
    }
}

/// The compact circular Home-nav control. The mascot is a real button so the
/// standby experience is discoverable without adding another tab or badge.
public struct AttnMascotBadge: View {
    private let size: CGFloat
    private let action: () -> Void

    public init(size: CGFloat = 50, action: @escaping () -> Void = {}) {
        self.size = size
        self.action = action
    }

    public var body: some View {
        Button(action: action) {
            Group {
                if let image = AttnMascotImage.badge {
                    Image(uiImage: image)
                        .resizable()
                        .interpolation(.high)
                        .scaledToFit()
                } else {
                    Circle()
                        .fill(
                            LinearGradient(
                                colors: [
                                    Color(red: 0, green: 159 / 255, blue: 254 / 255),
                                    Color(red: 249 / 255, green: 251 / 255, blue: 227 / 255)
                                ],
                                startPoint: .top,
                                endPoint: .bottom
                            )
                        )
                }
            }
            .frame(width: size, height: size)
            .contentShape(Circle())
        }
        .buttonStyle(.plain)
        .accessibilityLabel("Open standby display")
        .accessibilityHint("Shows the time, mascot, and priorities that need attention.")
    }
}

private enum AttnMascotImage {
    static let badge: UIImage? = {
        guard let data = Data(base64Encoded: AttnMascotBadgePNG.base64) else { return nil }
        return UIImage(data: data)
    }()

    static let image: UIImage? = {
        guard let data = Data(base64Encoded: AttnMascotPNG.base64) else { return nil }
        return UIImage(data: data)
    }()

    static let question: UIImage? = {
        guard let data = Data(base64Encoded: AttnMascotQuestionPNG.base64) else { return nil }
        return UIImage(data: data)
    }()
}

private enum AttnMascotPNG {
    static let base64 = ""
}


private enum AttnMascotQuestionPNG {
    static let base64 = ""
}


private enum AttnMascotBadgePNG {
    static let base64 = ""
}
